sys_script_client.script:
function onSubmit() {
   //Type appropriate comment here, and begin script below

   var shortDesc = g_form.getValue('short_description');

    // Check if the field is empty or just contains whitespace
    if (!shortDesc || shortDesc.trim() === "") {
        // Display an error message at the top of the form
        g_form.addErrorMessage('A clear Short Description is required before submitting this request.');

        // Highlight the field in red to draw attention
        g_form.setMandatory('short_description', true);

        // Return false to halt/cancel the form submission
        return false;
    }

    // Optional: Add a minimum character check to ensure it's a "clear" description
    if (shortDesc.trim().length < 10) {
        g_form.addErrorMessage('Please provide a more detailed Short Description (at least 10 characters).');
        return false;
    }
}
